SET NOCOUNT ON;
SELECT 'K_NPC_ITEM' AS tbl, COUNT(*) AS missing_refs FROM (SELECT [iItem01] AS v FROM [K_NPC_ITEM] UNION ALL SELECT [iItem02] AS v FROM [K_NPC_ITEM] UNION ALL SELECT [iItem03] AS v FROM [K_NPC_ITEM] UNION ALL SELECT [iItem04] AS v FROM [K_NPC_ITEM] UNION ALL SELECT [iItem05] AS v FROM [K_NPC_ITEM]) x WHERE v>0 AND v NOT IN (SELECT Num FROM ITEM);
SELECT 'K_MONSTER_ITEM' AS tbl, COUNT(*) AS missing_refs FROM (SELECT [iItem01] AS v FROM [K_MONSTER_ITEM] UNION ALL SELECT [iItem02] AS v FROM [K_MONSTER_ITEM] UNION ALL SELECT [iItem03] AS v FROM [K_MONSTER_ITEM] UNION ALL SELECT [iItem04] AS v FROM [K_MONSTER_ITEM] UNION ALL SELECT [iItem05] AS v FROM [K_MONSTER_ITEM]) x WHERE v>0 AND v NOT IN (SELECT Num FROM ITEM);
SELECT 'MAKE_ITEM' AS tbl, COUNT(*) AS missing_refs FROM (SELECT [iItemCode] AS v FROM [MAKE_ITEM]) x WHERE v>0 AND v NOT IN (SELECT Num FROM ITEM);
SELECT 'ITEM_UPGRADE' AS tbl, COUNT(*) AS missing_refs FROM (SELECT [nOriginItem] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nReqItem1] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nReqItem2] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nReqItem3] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nReqItem4] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nReqItem5] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nReqItem6] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nReqItem7] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nReqItem8] AS v FROM [ITEM_UPGRADE] UNION ALL SELECT [nGiveItem] AS v FROM [ITEM_UPGRADE]) x WHERE v>0 AND v NOT IN (SELECT Num FROM ITEM);
GO
